;s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),(224,23,'_wp_attached_file','2018/11/byrdword-how-to-focus.jpg'),(84,21,'_edit_lock','1539413364:1'),(85,21,'_edit_last','1'),(86,21,'_bbp_last_active_time','2015-10-05 16:50:53'),(87,21,'_bbp_forum_subforum_count','0'),(88,21,'_bbp_reply_count','0'),(89,21,'_bbp_total_reply_count','0'),(90,21,'_bbp_topic_count','0'),(91,21,'_bbp_total_topic_count','0'),(92,21,'_bbp_topic_count_hidden','0'),(142,23,'_bbp_last_topic_id','0'),(94,23,'_edit_lock','1445141027:5'),(95,23,'_edit_last','5'),(96,23,'_bbp_last_active_time','2015-10-05 20:00:48'),(97,23,'_bbp_forum_subforum_count','0'),(98,23,'_bbp_reply_count','0'),(99,23,'_bbp_total_reply_count','0'),(100,23,'_bbp_topic_count','0'),(101,23,'_bbp_total_topic_count','0'),(102,23,'_bbp_topic_count_hidden','0'),(201,17,'_edit_last','2'),(200,17,'_edit_lock','1493493535:2'),(232,27,'_edit_lock','1566564069:1'),(120,27,'_bbp_anonymous_name','Imran'),(121,27,'_bbp_anonymous_email','dev@cselian.com'),(122,27,'_bbp_anonymous_website',''),(123,27,'_bbp_forum_id','16'),(124,27,'_bbp_topic_id','24'),(125,27,'_bbp_author_ip','123.201.139.30'),(130,29,'_bbp_anonymous_name','Imran'),(131,29,'_bbp_anonymous_email','dev@cselian.com'),(132,29,'_bbp_anonymous_website',''),(133,29,'_bbp_forum_id','16'),(134,29,'_bbp_topic_id','29'),(135,29,'_bbp_author_ip','123.201.139.30'),(136,29,'_bbp_last_reply_id','0'),(137,29,'_bbp_last_active_id','29'),(138,29,'_bbp_last_active_time','2015-10-05 20:19:53'),(139,29,'_bbp_reply_count','0'),(140,29,'_bbp_reply_count_hidden','0'),(141,29,'_bbp_voice_count','1'),(143,23,'_bbp_last_reply_id','0'),(144,23,'_bbp_last_active_id','0'),(222,22,'_edit_lock','1541574897:1'),(223,22,'_edit_last','1'),(151,9,'_edit_lock','1446195336:1'),(152,9,'_edit_last','1'),(157,8,'_edit_lock','1453881541:2'),(158,8,'_edit_last','2'),(178,11,'_edit_last','1'),(177,11,'_edit_lock','1491029039:2'),(183,11,'_w