INSERT INTO `wp_wfIssues` VALUES (18181,1601471282,'new','heartbleed',1,'9cc241ad23332e598db0f9d52ced5850','a9959eec06826dfd6ed69474e057ef20','The HeartBleed openssl vulnerability scan has been deprecated','This scan is no longer necessary and has been removed from Wordfence. Please update to a current version of Wordfence.','a:0:{}'),(18182,1601471299,'new','configReadable',2,'dd7fd5a8863829d2f7ac912e3e9e76c4','dd7fd5a8863829d2f7ac912e3e9e76c4','Publicly accessible config, backup, or log file found: wp-content/debug.log','<a href=\"https://legacy.yieldmore.org/wp-content/debug.log\" target=\"_blank\">https://legacy.yieldmore.org/wp-content/debug.log</a> is publicly\n					accessible and may expose sensitive information about your site. Files such as this one are commonly\n					checked for by scanners such as WPScan and should be removed or made inaccessible.','a:3:{s:3:\"url\";s:49:\"https://legacy.yieldmore.org/wp-content/debug.log\";s:4:\"file\";s:20:\"wp-content/debug.log\";s:9:\"canDelete\";b:1;}'),(18183,1601471542,'new','wfUpgrade',1,'e3fd0b0ae36d6cd346df45a5bf2fe0b0','e3fd0b0ae36d6cd346df45a5bf2fe0b0','Your WordPress version is out of date','WordPress version 5.5.1 is now available. Please upgrade immediately to get the latest security updates from WordPress.','a:2:{s:14:\"currentVersion\";s:5:\"5.2.7\";s:10:\"newVersion\";s:5:\"5.5.1\";}'),(18184,1601471542,'new','wfPluginUpgrade',2,'a2f155967ace7a931fb1f4137650905b','a2f155967ace7a931fb1f4137650905b','The Plugin \"Cimy Swift SMTP\" needs an upgrade (2.6.2 -> 3.0.2).','You need to upgrade \"Cimy Swift SMTP\" to the newest version to ensure you have any security fixes the developer has released.','a:16:{s:4:\"Name\";s:15:\"Cimy Swift SMTP\";s:9:\"PluginURI\";s:67:\"http://www.marcocimmino.net/cimy-wordpress-plugins/cimy-swift-smtp/\";s:7:\"Version\";s:5:\"2.6.2\";s:11:\"Description\";s:119:\"Send email via SMTP (Compatible with GMAIL) <cite>By <a href=\"mailto:cimmino.marco@gmail.com\">Marco Cimmino</a>.</cit